/// <summary>
/// DebuC 16.06.23
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{       
    TransDate calcDate;
    int       counter;
    NDXFillItemScopeHistory    fillItemScopeHistory;
    date    enddate = endmth(prevmth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    date    startdate = Global::dateMthFwd(enddate,-13);
    container conUks  = ['ndx'];
    dataAreaId    dataAreaId;
    ;

    for(counter = 1; counter <= conlen(conUks); counter++)
    {
        dataAreaId = conpeek(conUks, counter);
        changecompany(dataAreaId)
        {
            for(calcDate = startdate;calcDate  <= enddate; calcDate = endmth(DateMthFwd(calcDate, 2)))
            {
                fillItemScopeHistory = new NDXFillItemScopeHistory();
                fillItemScopeHistory.NDX_setCalcMonth(KCS_HistoryCalcType::User, calcDate);
                fillItemScopeHistory.runOperation();
            }
            fillItemScopeHistory = new NDXFillItemScopeHistory();
            fillItemScopeHistory.NDX_setCalcMonth(KCS_HistoryCalcType::Standard, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
            fillItemScopeHistory.runOperation();
        }
    }        
}

/// <summary>
/// DebuC 18.04.24
/// </summary>
public static void createAndScheduleBatchJob()
{
    BatchHeader     batchHeader;
    StartDateTime   startTime;
    str batchGroupId = 'ArtikelHis'; 
    NDXFillItemScopeHistory fillItemScopeHistory = new NDXFillItemScopeHistory();


    startTime = DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())+1, str2Time('22:00:00'), DateTimeUtil::getUserPreferredTimeZone());

    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption('Artikelhistorie ermitteln');
    batchHeader.parmBatchGroup(batchGroupId);
    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, startTime);
    sysRecurrenceData = SysRecurrence::setRecurrenceNoEnd(sysRecurrenceData);
    sysRecurrenceData = SysRecurrence::setRecurrenceUnit(sysRecurrenceData, SysRecurrenceUnit::Day, 1);
    batchHeader.parmRecurrenceData(sysRecurrenceData);
    batchHeader.parmStartDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));    // job shouldn't start immediately

    batchHeader.addTask(fillItemScopeHistory);


    // Speichern des Batch-Headers, um den Job und seine Aufgaben zu registrieren
    batchHeader.save();
}
